import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReels() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [productNames, setProductNames] = useState({}); // Store product names by ID
    const [filters, setFilters] = useState({
        product: '',
        category: '',
        date: ''
    });
    const [categories, setCategories] = useState([]);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Initialize Remix Icons if available
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        
        loadReels();
        loadCategories();
    }, []);

    const loadCategories = async () => {
        try {
            const response = await ApiService.getCategories();
            if (response.success) {
                setCategories(response.data);
            }
        } catch (error) {
            console.error('Error loading categories:', error);
        }
    };

    const loadReels = async () => {
        try {
            setLoading(true);
            
            // Get seller reels from API
            // Note: In a real app, you would get the vendor ID from auth context or props
            const user = JSON.parse(localStorage.getItem('studioUser'));
            const vendorId = user?.vendor_id || 1; // Get from user data or fallback to 1
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                setReels(response.data);
                // Load product names for all reels
                await loadProductNames(response.data);
            } else {
                toast.error('Failed to load reels: ' + response.message);
                setReels([]);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
            setReels([]);
        }
    };

    const loadReelsWithFilters = async () => {
        try {
            setLoading(true);
            
            // Get seller reels from API with filters
            const user = JSON.parse(localStorage.getItem('studioUser'));
            const vendorId = user?.vendor_id || 1;
            
            // Prepare filters for API call
            const apiFilters = {};
            if (filters.category) apiFilters.category = filters.category;
            if (filters.date) apiFilters.date = filters.date;
            
            const response = await ApiService.getSellerReels(vendorId, apiFilters);
            
            if (response.success) {
                let filteredReels = response.data;
                
                // Apply product name filter on frontend since backend doesn't support it directly
                if (filters.product) {
                    // Load product names for filtering if not already loaded
                    if (Object.keys(productNames).length === 0) {
                        await loadProductNames(filteredReels);
                    }
                    
                    filteredReels = filteredReels.filter(reel => {
                        if (reel.product_ids && Array.isArray(reel.product_ids)) {
                            return reel.product_ids.some(productId => {
                                const productName = productNames[productId] || '';
                                return productName.toLowerCase().includes(filters.product.toLowerCase());
                            });
                        }
                        return false;
                    });
                }
                
                setReels(filteredReels);
            } else {
                toast.error('Failed to load reels: ' + response.message);
                setReels([]);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading reels with filters:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
            setReels([]);
        }
    };

    const handleFilter = async () => {
        await loadReelsWithFilters();
    };

    const handleClearFilter = async () => {
        setFilters({
            product: '',
            category: '',
            date: ''
        });
        await loadReels(); // Reload all reels
    };

    // Function to load product names from the database
    const loadProductNames = async (reelsData) => {
        try {
            // Collect all unique product IDs from all reels
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => {
                        // Ensure ID is a valid number before adding to set
                        const numericId = parseInt(id);
                        if (!isNaN(numericId) && numericId > 0) {
                            allProductIds.add(numericId);
                        }
                    });
                }
            });

            if (allProductIds.size === 0) {
                setProductNames({});
                return;
            }

            // Convert Set to Array of numbers
            const productIdsArray = Array.from(allProductIds);
            
            // Fetch real product names from the API
            const response = await ApiService.getProductNamesByIds(productIdsArray);
            if (response.success) {
                setProductNames(response.data);
            } else {
                // Fallback to placeholder names if API fails
                const productNamesMap = {};
                productIdsArray.forEach(id => {
                    productNamesMap[id] = `Product ${id}`;
                });
                setProductNames(productNamesMap);
            }
        } catch (error) {
            console.error('Error loading product names:', error);
            // Fallback to placeholder names if API fails
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => {
                        const numericId = parseInt(id);
                        if (!isNaN(numericId) && numericId > 0) {
                            allProductIds.add(numericId);
                        }
                    });
                }
            });
            
            const productIdsArray = Array.from(allProductIds);
            const productNamesMap = {};
            productIdsArray.forEach(id => {
                productNamesMap[id] = `Product ${id}`;
            });
            setProductNames(productNamesMap);
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Function to render product information for a reel
    const renderProductInfo = (productIds) => {
        if (!productIds || productIds.length === 0) {
            return <span className="text-muted">No products</span>;
        }
        
        // Display only the primary product name associated with the reel
        // Based on project requirements, show only the exact product selected for the reel
        const primaryProductId = parseInt(productIds[0]); // First product is the primary one selected during upload
        
        // Check if productId is valid
        if (isNaN(primaryProductId) || primaryProductId <= 0) {
            return <span className="text-muted">Unknown Product</span>;
        }
        
        return (
            <div>
                {productNames[primaryProductId] || `Product ${primaryProductId}`}
            </div>
        );
    };

    // Function to calculate reel count per product
    const getReelCountPerProduct = (productId) => {
        // Count how many reels have this product ID
        let count = 0;
        reels.forEach(reel => {
            if (reel.product_ids && Array.isArray(reel.product_ids)) {
                // Check if any of the reel's product IDs match the given productId
                const hasProduct = reel.product_ids.some(id => {
                    const reelProductId = parseInt(id);
                    return !isNaN(reelProductId) && reelProductId > 0 && reelProductId === productId;
                });
                if (hasProduct) {
                    count++;
                }
            }
        });
        return count;
    };

    // Function to handle viewing reels for a specific product
    const handleViewReelsForProduct = (productId) => {
        // Navigate to the product reels page
        navigate(`/studio/seller/reels/${productId}`);
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                    </div>
                    <div className="card-body">
                        {/* Filter Section */}
                        <div className="row mb-3">
                            <div className="col-md-3">
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Filter by product name"
                                    value={filters.product || ''}
                                    onChange={(e) => setFilters({...filters, product: e.target.value})}
                                />
                            </div>
                            <div className="col-md-3">
                                <select
                                    className="form-select"
                                    value={filters.category || ''}
                                    onChange={(e) => setFilters({...filters, category: e.target.value})}
                                >
                                    <option value="">All Categories</option>
                                    {categories.map(category => (
                                        <option key={category.id} value={category.id}>
                                            {category.name}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div className="col-md-3">
                                <input
                                    type="date"
                                    className="form-control"
                                    value={filters.date || ''}
                                    onChange={(e) => setFilters({...filters, date: e.target.value})}
                                />
                            </div>
                            <div className="col-md-3">
                                <button 
                                    className="btn btn-primary me-2" 
                                    onClick={handleFilter}
                                >
                                    Filter
                                </button>
                                <button 
                                    className="btn btn-secondary" 
                                    onClick={handleClearFilter}
                                >
                                    Clear
                                </button>
                            </div>
                        </div>
                        
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((reel) => (
                                            <tr key={reel.id}>
                                                <td>
                                                    {renderProductInfo(reel.product_ids)}
                                                </td>
                                                <td>
                                                    {/* Show reel count for the primary product only */}
                                                    {reel.product_ids && reel.product_ids.length > 0 ? (
                                                        <span className="badge bg-primary">
                                                            {getReelCountPerProduct(parseInt(reel.product_ids[0]))}
                                                        </span>
                                                    ) : (
                                                        <span className="badge bg-secondary">0</span>
                                                    )}
                                                </td>
                                                <td>{reel.title}</td>
                                                <td>{reel.category_name || 'N/A'}</td>
                                                <td>{getStatusBadge(reel.status)}</td>
                                                <td>{reel.views || 0}</td>
                                                <td>{reel.likes || 0}</td>
                                                <td>{reel.created_at ? new Date(reel.created_at).toLocaleDateString() : 'N/A'}</td>
                                                <td>
                                                    {/* Only showing the view button with proper styling - icon only */}
                                                    {reel.product_ids && reel.product_ids.length > 0 ? (
                                                        <button 
                                                            className="btn btn-sm btn-info"
                                                            onClick={() => handleViewReelsForProduct(parseInt(reel.product_ids[0]))}
                                                            title="View"
                                                        >
                                                            <i className="ri-eye-line"></i>
                                                        </button>
                                                    ) : (
                                                        <button 
                                                            className="btn btn-sm btn-secondary"
                                                            disabled
                                                            title="View"
                                                        >
                                                            <i className="ri-eye-line"></i>
                                                        </button>
                                                    )}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
